fn count_uppercase(text: &Vec<char>) -> u64 {
    let mut count: u64 = 0;
    for &c in text.iter() {
        // Check if c is in the ASCII range 'A'..='Z'
        if c >= 'A' && c <= 'Z' {
            count += 1;
        }
    }
    count
}

